# 애원복지 50호 웹진 빌드 스크립트 (테스트)
import html, json
E = html.escape

def img(code, alt, cls="ph"):
    return f'<button class="{cls}" type="button" data-full="img/{code}.jpg" aria-label="사진 크게 보기: {E(alt)}"><img src="img/{code}.jpg" alt="{E(alt)}" loading="lazy"></button>'

def gallery(codes, alt, caps=None):
    n = len(codes)
    items = []
    for i, c in enumerate(codes):
        cap = f'<figcaption>{E(caps[i])}</figcaption>' if caps and i < len(caps) and caps[i] else ''
        items.append(f'<figure>{img(c, (caps[i] if caps and i < len(caps) and caps[i] else alt))}{cap}</figure>')
    return f'<div class="gallery g{n}">{"".join(items)}</div>'

def paras(*ps):
    return "".join(f"<p>{E(p)}</p>" for p in ps)

def head(kicker, title, sub=None, page=None):
    pg = f'<span class="pg">지면 {E(page)}</span>' if page else ''
    s = f'<p class="sub">{E(sub)}</p>' if sub else ''
    return f'<header class="sec-head"><div class="kicker"><span>{E(kicker)}</span>{pg}</div><h2>{E(title)}</h2>{s}</header>'

def h3(t):
    return f'<h3>{E(t)}</h3>'

def news_cards(items):
    out = []
    for code, title, body in items:
        im = img(code, title) if code else '<div class="ph noimg" aria-hidden="true"></div>'
        out.append(f'<article class="card">{im}<div class="card-body"><h4>{E(title)}</h4><p>{E(body)}</p></div></article>')
    return f'<div class="cards">{"".join(out)}</div>'

sections = []  # (id, group, label, html)

