nav = []
groups = []
for sid, grp, label, _ in sections:
    if not groups or groups[-1][0] != grp:
        groups.append((grp, []))
    groups[-1][1].append((sid, label))
navhtml = '<a class="nav-cover" href="#cover">표지</a>'
for grp, items in groups:
    if len(items) == 1 and items[0][1] and grp in ("인사말", "애원뉴스", "주요사업 안내"):
        navhtml += f'<div class="nav-group"><a class="nav-top" href="#{items[0][0]}"><span>{E(grp)}</span><small>{E(items[0][1])}</small></a></div>'
    else:
        navhtml += f'<div class="nav-group"><p class="nav-label">{E(grp)}</p>' + "".join(f'<a href="#{s}">{E(l)}</a>' for s, l in items) + '</div>'

body = "".join(f'<section class="sec" id="{sid}" data-group="{E(grp)}">{h}</section>' for sid, grp, label, h in sections)

teasers = [("theme1", "BIN0035", "테마기획 1", "빛나는 당신을 위해, 리조이스 마음돌봄"), ("theme2", "BIN003F", "테마기획 2", "평생학습사업, 내가 그린 지구"), ("news-daycare", "BIN0021", "화보NEWS", "여섯 어린이집의 여름 이야기"), ("people", "BIN0011", "함께하는 사람들", "삼송한의원 박철 원장 인터뷰")]
teaser_html = "".join(f'<a class="teaser" href="#{s}"><img src="img/{c}.jpg" alt="" loading="lazy"><span class="t-k">{E(k)}</span><span class="t-t">{E(t)}</span></a>' for s, c, k, t in teasers)

tpl = open("template.html", encoding="utf-8").read()
out = tpl.replace("{{NAV}}", navhtml).replace("{{BODY}}", body).replace("{{TEASERS}}", teaser_html)
open("site/aewon-webzine-50.html", "w", encoding="utf-8").write(out)
print("ok", len(out))
